/// Returns true if and only if the difference between `a` and `b`
/// lies strictly within the open interval (−tol, tol).
/// Equivalently, |a - b| < tol.
/// 
/// # Panics
/// 
/// Panics if `tol <= 0`.
fn is_close_i8(a: i8, b: i8, tol: i8) -> bool {
    assert!(tol > 0, "tolerance must be strictly positive");
    // Promote to i16 to avoid overflow when subtracting i8 extremes.
    let diff = (a as i16 - b as i16).abs();
    diff < (tol as i16)
}

/// Given two input vectors `a` and `b` of equal, non-zero length, and
/// a strictly positive tolerance `tol`, returns a `Vec<bool>` of the same
/// length. Each position is `true` if and only if the corresponding elements
/// of `a` and `b` differ by strictly less than `tol`.
///
/// # Panics
///
/// Panics if `tol <= 0` or if `a.len() != b.len()`.
fn np_isclose(a: Vec<i8>, b: Vec<i8>, tol: i8) -> Vec<bool> {
    assert!(tol > 0, "tolerance must be strictly positive");
    assert_eq!(
        a.len(),
        b.len(),
        "input vectors must have the same length"
    );

    a.iter()
        .zip(b.iter())
        .map(|(&x, &y)| is_close_i8(x, y, tol))
        .collect()
}

